    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    int m;
    cin >> n >> m;

    vector<pair<long long, long long>> items(m);
    for (auto& [price, quantity] : items) {
        cin >> quantity >> price;
    }

    sort(items.rbegin(), items.rend());

    long long sum = 0;
    long long bought = 0;

    for (const auto& [price, quantity] : items) {
        if (bought == n) break;
        long long take = min(quantity, n - bought);
        sum += price * take;
        bought += take;
    }

    cout << sum;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    long long n;
    int m;
    cin >> n >> m;

    vector<pair<long long, long long>> items(m);
    for (auto& [amount, value] : items)
        cin >> amount >> value;

    sort(items.begin(), items.end(),
         [](const auto& lhs, const auto& rhs) {
             return lhs.second > rhs.second;
         });

    long long sum = 0;
    long long taken = 0;

    for (const auto& [amount, value] : items) {
        if (taken >= n)
            break;

        long long current = min(amount, n - taken);
        sum += current * value;
        taken += current;
    }

    cout << sum;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    int m;
    cin >> n >> m;

    vector<pair<long long, long long>> items(m);
    for (auto& [value, price] : items)
        cin >> value >> price;

    sort(items.begin(), items.end(),
         [](const auto& x, const auto& y) {
             return x.second > y.second;
         });

    long long sum = 0;
    for (const auto& [value, price] : items) {
        long long take = min(n, value);
        sum += take * price;
        n -= take;
        if (n == 0)
            break;
    }

    cout << sum;
    return 0;
}

